#!/usr/bin/env python3
"""Build a downstream app against the npm packages this commit would publish.

The packaging gates beside this file prove that a clean consumer can install
`@candid-core/schema` and `@candid-core/cli` and use them. They do not prove
that a real one still builds: ic-reactor pins both packages exactly, so a
change here that breaks its types, or that rewrites the modules it checks in,
is found only when someone raises the pins (#273). This script finds it before
the publish instead:

1. It packs both packages from a candid-core tree (this one, or the one
   `--candid-core` names), exactly as the release workflows would publish
   them, and installs the two tarballs into a scratch consumer to get a CLI.
2. With that CLI it regenerates every module the downstream checks in, and
   records the difference against the checked-in bytes. A module is one when
   its first line is the generator's header. Its source is either a
   `candid-core-cli gen` script of a workspace project (an example's `gen`) or
   the `.did` of the same name beside it (`packages/core/tests/fixtures`).
   Modules of packages outside the pnpm workspace (ic-reactor's `evals/`) are
   left out. A module with the header and no source is listed as not
   regenerated rather than guessed at.
3. It repins the downstream to the two tarballs' versions with its own tool
   (`stack.json` and `pnpm sync:stack`, as ic-reactor's repin does), points
   every `@candid-core/*` dependency at the tarballs through `pnpm.overrides`,
   installs, confirms that nothing in the install would load other bytes than
   the tarballs', and runs the downstream's own build, type checks and tests
   against the regenerated modules.

Drift never fails the run: a candid-core change often means to change the
generated modules, and the report says which ones moved and how. The exit
status says whose side a failure is on, and `downstream.yml` reads it:

- 1: the downstream's. A step failed (the repin included), the new CLI refused
  one of its `.did` files, its layout is one this script cannot read (a `gen`
  script that is not a plain call, a missing script, another package
  manager), or its install would load other bytes. A release can be dispatched
  to go out over it.
- 2: candid-core's. Building, packing or installing the two packages failed,
  the packed CLI does not write the header this script looks for, or the
  inputs are unusable (no wasm, no pnpm, a checkout with local changes).
- 3: this script crashed.

    python3 tests/fixtures/packaging/verify_downstream.py \\
        [--candid-core <tree to pack>] \\
        --downstream <a clean checkout of B3Pay/ic-reactor> --report <dir>

Before it runs, in the tree it packs, as for `verify_npm_cli_package.py`:
`npm ci` in the schema package (its build needs the pinned compiler) and the
wasm artifact built into `crates/candid-core-wasm/npm/wasm`; pnpm on PATH, at
the downstream's `packageManager` version (corepack). The report directory
gets `summary.md`, `report.json`, `drift.diff` and one log per step.
"""

import argparse
import hashlib
import json
import os
import pathlib
import re
import shlex
import shutil
import subprocess
import sys
import tarfile
import tempfile
import time
import traceback

HERE = pathlib.Path(__file__).resolve().parents[3]

DOWNSTREAM_FAILED, CANDID_CORE_FAILED, CRASHED = 1, 2, 3

PACKAGES = ("@candid-core/schema", "@candid-core/cli")

# The start of the first line of every module the generator writes
# (candid-core-ts's `generate_module`). A file whose first line is something
# else, such as a Prettier-formatted copy with a note on top, is not the
# generator's output. The packed CLI's own output is checked against it on
# every run, so a generator that changes its header fails here, on
# candid-core's side, instead of letting the checked-in modules drop out of
# the check unseen.
HEADER = "// Generated by candid-core-ts"

# The downstream's own scripts, run from its root after the install, in this
# order. They are what ic-reactor's CI runs over the generated modules and the
# `@candid-core/schema` types: the packages, their type checks (with e2e),
# their tests, the examples' type checks and the documentation snippets. Every
# step runs even when an earlier one failed, so one run shows all of them.
STEPS = ("build", "typecheck", "test", "typecheck:examples", "check:snippets")

# The downstream's repin: `stack.json` names the candid-core versions, and
# this script of its own rewrites every pin in the tree to them, the code pins
# included (vite-plugin's tests hold its CLI pin to the installed CLI).
REPIN = "sync:stack"

# What the runner gives a step to change the job with: files that set its
# environment, PATH, outputs and summary, and the runtime's tokens. The
# downstream's commands get none of them, so they cannot rewrite what the
# steps after this one run or report.
RUNNER_CONTROLS = re.compile(r"GITHUB_(ENV|PATH|OUTPUT|STATE|STEP_SUMMARY)|ACTIONS_\w*")

# Characters a shell would expand in a `gen` script. The CLI would receive the
# expansion, which this script cannot reproduce.
SHELL_EXPANDS = re.compile(r"[*?\[\]{}$~`\\]")


def run(args, cwd, **kw):
    return subprocess.run(args, cwd=cwd, check=True, text=True, **kw)


def git(directory, *args):
    # A GIT_DIR or GIT_INDEX_FILE inherited from a hook would point these at
    # another repository.
    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    env["GIT_LITERAL_PATHSPECS"] = "1"
    return subprocess.run(
        ["git", "-C", str(directory), *args],
        check=True,
        text=True,
        stdout=subprocess.PIPE,
        env=env,
    ).stdout


def pack(directory, into):
    out = run(
        ["npm", "pack", "--silent", "--pack-destination", str(into)],
        cwd=directory,
        stdout=subprocess.PIPE,
    )
    return into / out.stdout.strip().splitlines()[-1]


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def tarball_files(tarball):
    """Each regular file of an npm tarball, by its path in the package, to its digest."""
    files = {}
    with tarfile.open(tarball) as archive:
        for member in archive.getmembers():
            if member.isfile():
                # npm packs every file under one top directory, `package/`.
                files[member.name.split("/", 1)[1]] = sha256(archive.extractfile(member).read())
    return files


def directory_files(directory):
    """Each file of an installed package, by its path in the package, to its digest.

    pnpm writes `node_modules/.bin/` shims into a package's directory for the
    bins it may run; they are pnpm's, not the package's.
    """
    files = {}
    for path in directory.rglob("*"):
        rel = path.relative_to(directory).as_posix()
        if path.is_file() and not rel.startswith("node_modules/.bin/"):
            files[rel] = sha256(path.read_bytes())
    return files


def without_userinfo(url):
    return re.sub(r"(?<=://)[^@/]*@", "", url)


class Job:
    """One `candid-core-cli gen` run: its entries, where it runs, where it writes."""

    def __init__(self, cwd, entries, out_dir, origin, tracked_only):
        self.cwd = cwd
        self.entries = entries
        self.out_dir = out_dir
        self.origin = origin
        # A job read from a script writes what the script would write. A job
        # derived from a `.did` beside a module writes back only the files the
        # downstream tracks there: `scripts/check-snippets/app/generated` keeps
        # the modules and not their envelopes.
        self.tracked_only = tracked_only

    def modules(self, downstream):
        return [
            (self.out_dir / (pathlib.Path(e).name[: -len(".did")] + ".ts"))
            .relative_to(downstream)
            .as_posix()
            for e in self.entries
        ]


def script_job(downstream, manifest_rel, scripts, name):
    """The job a `candid-core-cli gen` script runs, or an error naming it."""
    command = scripts[name]
    where = f"{manifest_rel} script `{name}`"
    # pnpm runs `pre<name>` and `post<name>` around it (a formatter, say),
    # which this script would not.
    hooks = [hook for hook in (f"pre{name}", f"post{name}") if hook in scripts]
    if hooks:
        raise SystemExit(f"{where} has {', '.join(hooks)} around it, which this check does not reproduce")
    try:
        argv = shlex.split(command)
    except ValueError as error:
        raise SystemExit(f"{where} does not parse ({error}): {command!r}")
    # Anything but a plain call (another command around it, a flag this script
    # does not know, a glob) would make the regenerated set a guess.
    if argv[:2] != ["candid-core-cli", "gen"]:
        raise SystemExit(
            f"{where} is not a plain `candid-core-cli gen` call, so this check "
            f"cannot tell what it writes: {command!r}"
        )
    entries, out = [], None
    rest = iter(argv[2:])
    for argument in rest:
        if SHELL_EXPANDS.search(argument):
            raise SystemExit(f"{where} has {argument!r}, which a shell expands: {command!r}")
        if argument == "-o" and out is None:
            out = next(rest, None)
            if out is None:
                raise SystemExit(f"{where} ends with `-o`: {command!r}")
        elif argument.endswith(".did") and not argument.startswith("-"):
            entries.append(argument)
        else:
            raise SystemExit(
                f"{where} has {argument!r}, which this check does not "
                f"reproduce: {command!r}"
            )
    if not entries:
        raise SystemExit(f"{where} names no .did: {command!r}")
    package_dir = (downstream / manifest_rel).parent
    out_dir = pathlib.Path(os.path.normpath(package_dir / (out or ".")))
    if out_dir != downstream and downstream not in out_dir.parents:
        raise SystemExit(f"{where} writes outside the downstream: {command!r}")
    return Job(package_dir, entries, out_dir, where, False)


def workspace_projects(downstream, env):
    """The pnpm workspace's project directories, as pnpm itself lists them."""
    listed = subprocess.run(
        ["pnpm", "ls", "--recursive", "--depth", "-1", "--json"],
        cwd=downstream,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=env,
    )
    if listed.returncode != 0:
        raise SystemExit(f"`pnpm ls --recursive` failed in the downstream: {listed.stderr.strip()}")
    projects = {pathlib.Path(os.path.realpath(p["path"])) for p in json.loads(listed.stdout)}
    if downstream not in projects:
        raise SystemExit("`pnpm ls --recursive` does not list the downstream's root")
    return sorted(projects)


def discover(downstream, tracked, projects):
    """The jobs that regenerate the checked-in modules, the modules, and those left out."""
    tracked_set = set(tracked)
    manifests = {
        (downstream / rel).parent for rel in tracked if pathlib.PurePosixPath(rel).name == "package.json"
    }
    workspace = set(projects)

    def in_workspace(rel):
        # The package a file belongs to is the nearest directory above it with
        # a package.json; it is in the workspace when pnpm lists that one.
        for directory in (downstream / rel).parents:
            if directory in manifests:
                return directory in workspace
            if directory == downstream:
                break
        return True

    modules, outside = [], []
    for rel in tracked:
        path = downstream / rel
        if not rel.endswith(".ts") or path.is_symlink():
            continue
        with path.open(encoding="utf-8", errors="replace") as handle:
            if handle.readline().startswith(HEADER):
                (modules if in_workspace(rel) else outside).append(rel)

    jobs = []
    for project in projects:
        manifest = project / "package.json"
        rel = manifest.relative_to(downstream).as_posix()
        try:
            scripts = json.loads(manifest.read_text()).get("scripts") or {}
        except (OSError, ValueError) as error:
            raise SystemExit(f"{rel} does not read as JSON: {error}")
        for name, command in sorted(scripts.items()):
            # `--check` writes nothing, so a `gen:check` script is not a source.
            if "candid-core-cli gen" in command and "--check" not in command:
                jobs.append(script_job(downstream, rel, scripts, name))

    covered = {m for job in jobs for m in job.modules(downstream)}
    beside, unreached = {}, []
    for rel in modules:
        if rel in covered:
            continue
        did = rel[: -len(".ts")] + ".did"
        if did in tracked_set:
            beside.setdefault(pathlib.PurePosixPath(rel).parent, []).append(
                pathlib.PurePosixPath(did).name
            )
        else:
            unreached.append(rel)
    for directory, entries in sorted(beside.items()):
        cwd = downstream / directory
        jobs.append(Job(cwd, sorted(entries), cwd, f"the .did beside each module in {directory}/", True))
    return jobs, modules, unreached, outside


def regenerate(downstream, jobs, cli_js, work, tracked_set):
    """Run every job; returns the paths written and the jobs that failed."""
    written, failures = [], []
    for index, job in enumerate(jobs):
        scratch = work / f"gen-{index}"
        scratch.mkdir()
        proc = subprocess.run(
            ["node", str(cli_js), "gen", *job.entries, "-o", str(scratch)],
            cwd=job.cwd,
            text=True,
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        if proc.returncode != 0:
            failures.append(
                {
                    "origin": job.origin,
                    "entries": job.entries,
                    "exit": proc.returncode,
                    "output": (proc.stdout + proc.stderr).strip(),
                }
            )
            continue
        wanted = set(job.modules(downstream))
        for produced in sorted(scratch.iterdir()):
            destination = job.out_dir / produced.name
            rel = destination.relative_to(downstream).as_posix()
            if job.tracked_only and rel not in wanted and rel not in tracked_set:
                continue
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(produced, destination)
            written.append(rel)
    return sorted(set(written)), failures


def ignored(downstream, paths):
    """The paths of `paths` the downstream's .gitignore files ignore."""
    if not paths:
        return set()
    proc = subprocess.run(
        ["git", "-C", str(downstream), "check-ignore", "-z", "--stdin"],
        input="\0".join(paths),
        text=True,
        stdout=subprocess.PIPE,
        env={k: v for k, v in os.environ.items() if not k.startswith("GIT_")},
    )
    if proc.returncode not in (0, 1):  # 1: none of them is ignored
        raise SystemExit(f"`git check-ignore` exited {proc.returncode} in the downstream")
    return {p for p in proc.stdout.split("\0") if p}


def point_at_tarballs(downstream, tarballs):
    """Override every `@candid-core/*` dependency with the packed tarballs."""
    manifest_path = downstream / "package.json"
    manifest = json.loads(manifest_path.read_text())
    overrides = manifest.setdefault("pnpm", {}).setdefault("overrides", {})
    for name, tarball in tarballs.items():
        overrides[name] = f"file:{tarball}"
    manifest_path.write_text(json.dumps(manifest, indent=2) + "\n")


# A module specifier naming `@candid-core/schema`, in code from which comments
# are taken out first: a JSDoc line that names the package is not an import.
SCHEMA_SPECIFIER = re.compile(r"""["'`]@candid-core/schema(?:["'`]|/)""")
BLOCK_COMMENT = re.compile(r"/\*.*?\*/", re.S)
LINE_COMMENT = re.compile(r"(?:^|(?<=\s))//[^\n]*", re.M)


def imports_schema(package_dir):
    """The shipped JavaScript and declaration files of a package that name the schema package."""
    suffixes = (".js", ".mjs", ".cjs", ".d.ts", ".d.mts", ".d.cts")
    hits = []
    for path in sorted(package_dir.rglob("*")):
        if path.is_file() and path.name.endswith(suffixes):
            code = LINE_COMMENT.sub("", BLOCK_COMMENT.sub("", path.read_text(errors="replace")))
            if SCHEMA_SPECIFIER.search(code):
                hits.append(path.relative_to(package_dir).as_posix())
    return hits


def foreign_links(downstream, projects, expected, cli_imports):
    """Where the install would load other bytes than the tarballs' for a `@candid-core` package.

    Every `node_modules/@candid-core/<name>` link of a workspace project, of
    pnpm's hidden hoist, and of each package in pnpm's virtual store has to
    reach a directory holding exactly the files of that package's tarball. An
    override that did not reach a dependency would leave another copy, most
    likely the published one, under the downstream, and the run would pass for
    the wrong reason.

    One kind of link is allowed, and reported. Where a project depends on the
    CLI and not on the schema (ic-reactor's vite-plugin), pnpm resolves the
    CLI's optional `@candid-core/schema` peer from the registry when the
    registry has that version, because an override to a tarball is not a peer
    range. That link sits beside the CLI, so only the CLI's own code could load
    it, and it is allowed only while the CLI's shipped JavaScript and
    declarations name no `@candid-core/schema` (`cli_imports` lists the files
    that do).
    """
    store = downstream / "node_modules" / ".pnpm"
    if not store.is_dir():
        raise SystemExit(f"{store} does not exist after the install")
    verdicts = {}

    def ours(name, directory):
        key = (name, os.path.realpath(directory))
        if key not in verdicts:
            verdicts[key] = directory_files(pathlib.Path(key[1])) == expected[name]
        return verdicts[key]

    def label(path):
        return path.relative_to(downstream).as_posix() or "."

    holders = [(label(p), p / "node_modules", True) for p in projects]
    holders.append(("node_modules/.pnpm/node_modules", store / "node_modules", False))
    holders += [(label(e), e / "node_modules", False) for e in sorted(store.iterdir()) if e.is_dir() and e.name != "node_modules"]
    refused, allowed, reached, users = [], [], set(), {}
    for where, modules, is_project in holders:
        for name in PACKAGES:
            link = modules / name
            if not link.is_symlink():
                continue
            if ours(name, link):
                reached.add(name)
                if is_project and name == "@candid-core/cli":
                    users.setdefault(os.path.realpath(link), []).append(where)
                continue
            cli = modules / "@candid-core" / "cli"
            peer_of_cli = (
                not is_project
                and name == "@candid-core/schema"
                and cli.is_dir()
                and not cli.is_symlink()
                and ours("@candid-core/cli", cli)
            )
            target = os.path.realpath(link)
            target = label(pathlib.Path(target)) if downstream in pathlib.Path(target).parents else target
            if peer_of_cli and not cli_imports:
                allowed.append({"holder": where, "target": target, "cli": os.path.realpath(cli)})
            else:
                refused.append(f"{where} links {name} to {target}")
    for item in allowed:
        item["projects"] = sorted(users.get(item.pop("cli"), []))
    refused += [f"no project resolves {name} to its tarball" for name in PACKAGES if name not in reached]
    return refused, allowed


def step(name, command, cwd, logs, env):
    log = logs / f"{len(list(logs.iterdir())) + 1:02d}-{name.replace(':', '-')}.log"
    grouped = os.environ.get("GITHUB_ACTIONS") == "true"
    print(f"::group::{name}" if grouped else f"==> {name}", flush=True)
    started = time.monotonic()
    with log.open("w") as handle:
        proc = subprocess.Popen(
            command,
            cwd=cwd,
            text=True,
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env=env,
        )
        for line in proc.stdout:
            sys.stdout.write(line)
            handle.write(line)
        code = proc.wait()
    seconds = round(time.monotonic() - started)
    if grouped:
        print("::endgroup::", flush=True)
    print(f"{name}: {'pass' if code == 0 else f'fail (exit {code})'} in {seconds} s", flush=True)
    return {
        "name": name,
        "command": " ".join(command),
        "exit": code,
        "seconds": seconds,
        "log": log.relative_to(logs.parent).as_posix(),
    }


def summary(report):
    core, down = report["candid_core"], report["downstream"]
    lines = ["## Downstream check", ""]
    where = f"{down['url']} at `{down['commit']}`"
    web = down["url"].removesuffix(".git")
    if web.startswith("https://github.com/"):
        where = f"[{web.removeprefix('https://github.com/')}@{down['commit'][:12]}]({web}/commit/{down['commit']})"
    packed = (
        f"packed as `@candid-core/schema` {core['schema']['version']} and "
        f"`@candid-core/cli` {core['cli']['version']}"
        if "cli" in core
        else "not packed"
    )
    tools = f" with Node {down['node']} and pnpm {down['pnpm']}" if "pnpm" in down else ""
    lines.append(
        f"candid-core `{core['commit']}`{' with uncommitted changes' if core['dirty'] else ''}, "
        f"{packed}, against {where} (`{down['ref']}`){tools}."
    )
    lines.append("")
    if report["ok"]:
        lines.append("**Result: pass.** Every step passed. Drift does not fail this check.")
    else:
        failed = [s["name"] for s in report["steps"] if s["exit"] != 0]
        reasons = []
        if failed:
            reasons.append(f"{len(failed)} of {len(report['steps'])} steps failed ({', '.join(failed)})")
        if report["generation_failures"]:
            reasons.append(f"{len(report['generation_failures'])} generation runs failed")
        if report.get("error"):
            reasons.append(report["error"])
        side = "ic-reactor's side" if report["side"] == "downstream" else "candid-core's side"
        lines.append(f"**Result: fail, on {side}.** {'; '.join(reasons)}.")
    drift = report.get("drift")
    if drift is None:
        return "\n".join(lines) + "\n"
    lines += ["", "### Generated modules", ""]
    changed = [f for f in drift["files"] if f["status"] in ("changed", "new")]
    regenerated = sum(1 for f in drift["files"] if f["path"].endswith(".ts"))
    lines.append(
        f"{len(drift['modules'])} checked-in modules of the workspace carry the generator's "
        f"header. {len(drift['jobs'])} `gen` runs regenerated {regenerated} modules and "
        f"{len(drift['files']) - regenerated} envelopes: {len(changed)} of those "
        f"{len(drift['files'])} files differ from the checked-in bytes (`drift.diff`)."
    )
    if changed:
        lines += ["", "| File | Status |", "| --- | --- |"]
        lines += [f"| `{f['path']}` | {f['status']} |" for f in changed]
    ignored_files = [f["path"] for f in drift["files"] if f["status"] == "ignored"]
    if ignored_files:
        lines += ["", f"Written and ignored by the downstream's .gitignore: {', '.join(f'`{p}`' for p in ignored_files)}."]
    if drift["unreached"]:
        lines += ["", "Not regenerated, no source found:", ""]
        lines += [f"- `{m}`" for m in drift["unreached"]]
    if drift["outside"]:
        lines += ["", "Outside the pnpm workspace, left out:", ""]
        lines += [f"- `{m}`" for m in drift["outside"]]
    for failure in report["generation_failures"]:
        lines += ["", f"Generation failed for {failure['origin']} (exit {failure['exit']}):", "", "```", failure["output"], "```"]
    for item in report.get("install", {}).get("allowed", []):
        lines += [
            "",
            f"The install links `{item['target']}` beside the CLI (`{item['holder']}`), "
            "the registry's copy, as the CLI's optional peer for "
            f"{', '.join(f'`{p}`' for p in item['projects']) or 'a project'}, which depends on the "
            "CLI and not on the schema. The CLI's shipped JavaScript and declarations name no "
            "`@candid-core/schema`, so nothing loads it.",
        ]
    if report["steps"]:
        lines += ["", "### Steps", "", "| Step | Command | Result | Time |", "| --- | --- | --- | --- |"]
        for s in report["steps"]:
            result = "pass" if s["exit"] == 0 else f"**fail** (exit {s['exit']})"
            lines.append(f"| {s['name']} | `{s['command']}` | {result} | {s['seconds']} s |")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n", 1)[0])
    parser.add_argument("--candid-core", type=pathlib.Path, default=HERE)
    parser.add_argument("--downstream", required=True, type=pathlib.Path)
    parser.add_argument("--report", required=True, type=pathlib.Path)
    args = parser.parse_args()
    repo = args.candid_core.resolve()
    schema = repo / "crates" / "candid-core-ts" / "ts"
    cli = repo / "crates" / "candid-core-wasm" / "npm"
    downstream = args.downstream.resolve()
    report_dir = args.report.resolve()

    if shutil.which("pnpm") is None:
        raise SystemExit("pnpm is not on PATH; enable it with corepack, as the downstream's CI does")
    if not (cli / "wasm" / "candid_core_wasm_bg.wasm").exists():
        raise SystemExit(
            f"the wasm artifact is missing: build it in {cli} first "
            "(`npm run build`), or the CLI tarball ships no WebAssembly"
        )
    if pathlib.Path(os.path.realpath(git(downstream, "rev-parse", "--show-toplevel").strip())) != downstream:
        raise SystemExit(f"{downstream} is not the top of its git checkout")
    if git(downstream, "status", "--porcelain", "--untracked-files=all"):
        raise SystemExit(
            f"{downstream} has local changes; the drift is measured against "
            "its checked-in bytes, so it must be a clean checkout"
        )
    if report_dir.exists() and any(report_dir.iterdir()):
        raise SystemExit(f"{report_dir} is not empty")
    logs = report_dir / "steps"
    logs.mkdir(parents=True, exist_ok=True)

    remote = subprocess.run(
        ["git", "-C", str(downstream), "remote", "get-url", "origin"],
        text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
    ).stdout.strip()
    report = {
        "candid_core": {
            "commit": git(repo, "rev-parse", "HEAD").strip(),
            "dirty": bool(git(repo, "status", "--porcelain", "--untracked-files=no").strip()),
        },
        "downstream": {
            "url": without_userinfo(remote) or str(downstream),
            "ref": git(downstream, "rev-parse", "--abbrev-ref", "HEAD").strip(),
            "commit": git(downstream, "rev-parse", "HEAD").strip(),
        },
        "generation_failures": [],
        "steps": [],
    }

    # A downstream this script cannot read, or a command of its own that fails,
    # stops the run; the report says why, as well as stderr.
    stage = "candid-core"
    try:
        with tempfile.TemporaryDirectory() as tmp:
            work = pathlib.Path(tmp)

            # 1. The two tarballs a publish from this commit would upload. The
            #    schema's `dist/` is a build product excluded from git, so it is
            #    built first, as the sibling gates do.
            run(["npm", "run", "build"], schema, stdout=subprocess.DEVNULL)
            tarballs = {"@candid-core/schema": pack(schema, work), "@candid-core/cli": pack(cli, work)}
            for key, directory in (("schema", schema), ("cli", cli)):
                tarball = tarballs[f"@candid-core/{key}"]
                report["candid_core"][key] = {
                    "version": json.loads((directory / "package.json").read_text())["version"],
                    "tarball": tarball.name,
                    "sha256": sha256(tarball.read_bytes()),
                }
            expected = {name: tarball_files(tarball) for name, tarball in tarballs.items()}
            consumer = work / "consumer"
            consumer.mkdir()
            (consumer / "package.json").write_text(json.dumps({"name": "downstream-cli", "private": True}))
            run(
                ["npm", "install", "--silent", "--no-audit", "--no-fund", *map(str, tarballs.values())],
                cwd=consumer,
            )
            cli_js = consumer / "node_modules" / "@candid-core" / "cli" / "bin" / "cli.js"
            (work / "probe").mkdir()
            (work / "probe" / "probe.did").write_text("service : {};\n")
            run(["node", str(cli_js), "gen", "probe.did", "-o", "."], work / "probe", stdout=subprocess.DEVNULL)
            first = (work / "probe" / "probe.ts").read_text().split("\n", 1)[0]
            if not first.startswith(HEADER):
                raise SystemExit(
                    f"the packed CLI's modules start with {first!r}, not {HEADER!r}: "
                    "update HEADER, or the checked-in modules drop out of this check"
                )
            stage = "downstream"

            env = {k: v for k, v in os.environ.items() if not RUNNER_CONTROLS.fullmatch(k)}
            env["CI"] = "true"
            manifest = json.loads((downstream / "package.json").read_text())
            manager = manifest.get("packageManager", "")
            if not manager.startswith("pnpm@"):
                raise SystemExit(
                    f"the downstream's packageManager is {manager!r}; this check "
                    "installs through pnpm overrides and knows no other manager"
                )
            missing = [s for s in (REPIN, *STEPS) if s not in (manifest.get("scripts") or {})]
            if missing:
                raise SystemExit(f"the downstream has no script {', '.join(missing)}")
            if not (downstream / "stack.json").is_file():
                raise SystemExit("the downstream has no stack.json to repin with")
            for tool in ("node", "pnpm"):
                report["downstream"][tool] = run([tool, "--version"], downstream, stdout=subprocess.PIPE, env=env).stdout.strip()

            # 2. Regenerate, then measure against the checked-in bytes before the
            #    repin and the install touch the tree.
            tracked = [p for p in git(downstream, "ls-files", "-z").split("\0") if p]
            projects = workspace_projects(downstream, env)
            jobs, modules, unreached, outside = discover(downstream, tracked, projects)
            written, report["generation_failures"] = regenerate(downstream, jobs, cli_js, work, set(tracked))
            fresh = [p for p in written if p not in set(tracked)]
            skipped = ignored(downstream, fresh)
            new = [p for p in fresh if p not in skipped]
            if new:
                git(downstream, "add", "--intent-to-add", "--", *new)
            measured = [p for p in written if p not in skipped]
            diff = git(downstream, "diff", "--no-color", "--no-ext-diff", "--", *measured) if measured else ""
            (report_dir / "drift.diff").write_text(diff)
            changed = set(git(downstream, "diff", "--name-only", "-z", "--", *measured).split("\0")) if measured else set()
            report["drift"] = {
                "jobs": [{"origin": j.origin, "entries": j.entries} for j in jobs],
                "modules": modules,
                "files": [
                    {
                        "path": p,
                        "status": "ignored" if p in skipped else "new" if p in new else "changed" if p in changed else "unchanged",
                    }
                    for p in written
                ],
                "unreached": unreached,
                "outside": outside,
            }

            # 3. Repin to the tarballs' versions with the downstream's own tool,
            #    then install through the tarballs, confirm that nothing else
            #    would be loaded, and run the downstream's own checks.
            stack_path = downstream / "stack.json"
            stack = json.loads(stack_path.read_text())
            stack["candid-core"] = {name: report["candid_core"][name.split("/")[1]]["version"] for name in PACKAGES}
            stack_path.write_text(json.dumps(stack, indent=2) + "\n")
            report["steps"].append(step("repin", ["pnpm", "run", REPIN], downstream, logs, env))
            point_at_tarballs(downstream, tarballs)
            install = step("install", ["pnpm", "install", "--no-frozen-lockfile"], downstream, logs, env)
            report["steps"].append(install)
            if install["exit"] == 0:
                cli_imports = imports_schema(cli_js.parents[1])
                refused, allowed = foreign_links(downstream, projects, expected, cli_imports)
                report["install"] = {"cli_imports_schema": cli_imports, "allowed": allowed, "refused": refused}
                if refused:
                    report["error"] = "the install would load other bytes than the tarballs': " + "; ".join(refused)
                else:
                    for name in STEPS:
                        report["steps"].append(step(name, ["pnpm", "run", name], downstream, logs, env))
    except SystemExit as error:
        if not isinstance(error.code, str):
            raise
        report["error"] = error.code
    except subprocess.CalledProcessError as error:
        report["error"] = f"`{' '.join(map(str, error.cmd))}` exited {error.returncode}"
    if report.get("error"):
        print(report["error"], file=sys.stderr)
    report["side"] = stage if report.get("error") else "downstream"

    report["ok"] = (
        not report.get("error")
        and not report["generation_failures"]
        and len(report["steps"]) == 2 + len(STEPS)
        and all(s["exit"] == 0 for s in report["steps"])
    )
    (report_dir / "report.json").write_text(json.dumps(report, indent=2) + "\n")
    text = summary(report)
    (report_dir / "summary.md").write_text(text)
    print(text)
    if report["ok"]:
        return 0
    return CANDID_CORE_FAILED if report["side"] == "candid-core" else DOWNSTREAM_FAILED


if __name__ == "__main__":
    try:
        sys.exit(main())
    except SystemExit as error:
        # A refusal before the report exists: the inputs are unusable.
        if not isinstance(error.code, str):
            raise
        print(error.code, file=sys.stderr)
        sys.exit(CANDID_CORE_FAILED)
    except Exception:
        traceback.print_exc()
        sys.exit(CRASHED)
